/* LevelUp Life · edición personal 1.0 · sin rastreadores ni servidor */
(()=>{
'use strict';
const K='levelup-life-v1', SESSION_KEY='levelup-focus-v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const day=(d=new Date())=>{const a=new Date(d.getTime()-d.getTimezoneOffset()*60000);return a.toISOString().slice(0,10)};
const dateOffset=n=>{const d=new Date();d.setDate(d.getDate()+n);return day(d)};
const weekKey=(t=new Date())=>{const d=new Date(t);d.setHours(12,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);return day(d)};
const fmtDate=(d,opts={day:'numeric',month:'long'})=>new Date(d+'T12:00:00').toLocaleDateString('es-CR',opts);
const weekdays=['L','M','M','J','V','S','D'];
const categories={personal:{icon:'🌱',color:'#70dac2',title:'Personal'},estudio:{icon:'📚',color:'#aa99ff',title:'Estudio'},salud:{icon:'💪',color:'#fcac84',title:'Salud'},trabajo:{icon:'💻',color:'#79b8ff',title:'Proyectos'},hogar:{icon:'🏡',color:'#facd80',title:'Hogar'},otro:{icon:'🎯',color:'#ef9aca',title:'Otro'}};
const difficulty={easy:{name:'Fácil',xp:20,coins:8},medium:{name:'Normal',xp:40,coins:15},hard:{name:'Épica',xp:75,coins:30}};
const nav=[['dashboard','◈','Inicio'],['quests','⚔','Misiones'],['habits','◉','Hábitos'],['focus','◎','Modo enfoque'],['challenges','✧','Desafíos'],['shop','◇','Recompensas'],['achievements','♛','Logros'],['analytics','▥','Estadísticas'],['calendar','▦','Calendario'],['journal','✎','Mi diario'],['settings','⚙','Ajustes']];
const achievements=[
{id:'firstquest',icon:'⚔️',title:'Primer paso',desc:'Completá tu primera misión.',ok:()=>count('quest')>=1},
{id:'firsthabit',icon:'🌱',title:'Constancia',desc:'Registrá tu primer hábito.',ok:()=>count('habit')>=1},
{id:'level3',icon:'⭐',title:'Ascenso',desc:'Alcanzá el nivel 3.',ok:()=>level().value>=3},
{id:'xp500',icon:'💎',title:'Diamante',desc:'Acumulá 500 XP.',ok:()=>state.xp>=500},
{id:'quests10',icon:'🗡️',title:'Aventurero',desc:'Completá 10 misiones.',ok:()=>count('quest')>=10},
{id:'habit20',icon:'🌿',title:'Raíces profundas',desc:'Marcá hábitos 20 veces.',ok:()=>count('habit')>=20},
{id:'streak3',icon:'🔥',title:'En racha',desc:'Mantené 3 días de actividad.',ok:()=>bestStreak()>=3},
{id:'streak7',icon:'🏆',title:'Semana legendaria',desc:'Mantené 7 días de actividad.',ok:()=>bestStreak()>=7},
{id:'focus60',icon:'🧠',title:'Mente clara',desc:'Completá 60 min. de enfoque.',ok:()=>state.focus.reduce((a,f)=>a+f.minutes,0)>=60},
{id:'focus300',icon:'🪐',title:'Concentración total',desc:'Completá 300 min. de enfoque.',ok:()=>state.focus.reduce((a,f)=>a+f.minutes,0)>=300},
{id:'redeem',icon:'🎁',title:'Te lo ganaste',desc:'Canjeá tu primera recompensa.',ok:()=>state.redemptions.length>0},
{id:'journal5',icon:'📝',title:'Mi historia',desc:'Escribí 5 entradas en tu diario.',ok:()=>state.journal.length>=5}];
const challenges=[
{id:'twoquests',title:'Dos victorias',desc:'Completá 2 misiones hoy',icon:'⚔️',max:2,period:'daily',xp:45,coins:20,current:()=>dailyCount('quest')},
{id:'onehabit',title:'Pequeña gran acción',desc:'Registrá un hábito hoy',icon:'🌿',max:1,period:'daily',xp:20,coins:12,current:()=>dailyCount('habit')},
{id:'focus25',title:'Sin distracciones',desc:'Acumulá 25 minutos de enfoque hoy',icon:'🧠',max:25,period:'daily',xp:40,coins:15,current:()=>state.focus.filter(x=>x.date===day()).reduce((a,f)=>a+f.minutes,0)},
{id:'week7',title:'Guerrero de la semana',desc:'Completá 7 misiones esta semana',icon:'🏅',max:7,period:'weekly',xp:125,coins:60,current:()=>state.ledger.filter(x=>x.kind==='quest'&&x.date>=weekKey()).length}];
function seed(){return {schema:1,profile:{name:'Aventurero',avatar:'⚡',dailyGoal:100},xp:0,coins:0,quests:[
{id:uid(),title:'Organizar mis prioridades',category:'personal',difficulty:'easy',repeat:'daily',createdAt:day(),doneDates:[],description:'Elegí las tres cosas más importantes del día.'},
{id:uid(),title:'Estudiar 20 minutos',category:'estudio',difficulty:'medium',repeat:'daily',createdAt:day(),doneDates:[],description:'Dedicá tiempo a aprender algo nuevo.'},
{id:uid(),title:'Avanzar en mi proyecto',category:'trabajo',difficulty:'medium',repeat:'one',createdAt:day(),doneDates:[],description:'Da un paso concreto hacia una meta personal.'},
{id:uid(),title:'Caminar 15 minutos',category:'salud',difficulty:'easy',repeat:'daily',createdAt:day(),doneDates:[],description:'Dale un respiro a tu mente.'}
],habits:[
{id:uid(),title:'Leer 10 minutos',category:'estudio',schedule:'all',history:[],createdAt:day()},
{id:uid(),title:'Mover el cuerpo',category:'salud',schedule:'all',history:[],createdAt:day()},
{id:uid(),title:'Escribir una reflexión',category:'personal',schedule:'all',history:[],createdAt:day()}
],rewards:[{id:uid(),title:'Una tarde de videojuegos',icon:'🎮',cost:180},{id:uid(),title:'Ver una película',icon:'🍿',cost:120},{id:uid(),title:'Un antojo especial',icon:'🍰',cost:250}],redemptions:[],ledger:[],focus:[],journal:[],claims:[],createdAt:day()};}
function load(){try{const raw=localStorage.getItem(K);if(!raw)return seed();const v=JSON.parse(raw);if(v&&v.schema===1&&Array.isArray(v.quests)&&Array.isArray(v.ledger)&&Array.isArray(v.habits)){const s=seed();return {...s,...v,profile:{...s.profile,...v.profile},focus:Array.isArray(v.focus)?v.focus:[],journal:Array.isArray(v.journal)?v.journal:[],claims:Array.isArray(v.claims)?v.claims:[],redemptions:Array.isArray(v.redemptions)?v.redemptions:[],rewards:Array.isArray(v.rewards)?v.rewards:s.rewards};}}catch(e){console.warn('El guardado no se pudo leer',e)}return seed()}
let state=load();const ui={view:'dashboard',filter:'all',questFilter:'all',habitFilter:'all',calOffset:0,selectedDate:day(),focusLength:25,focusEnd:0,focusRemaining:25*60,focusRunning:false,focusTask:'',focusPausedAt:0};
const store=()=>{try{localStorage.setItem(K,JSON.stringify(state));return true}catch(e){toast('No hay espacio para guardar; exportá un respaldo.','error');return false}};
const count=kind=>state.ledger.filter(x=>x.kind===kind).length;
const dailyCount=(kind,d=day())=>state.ledger.filter(x=>x.kind===kind&&x.date===d).length;
const todayXP=()=>state.ledger.filter(x=>x.date===day()).reduce((a,l)=>a+l.xp,0);
const dailyMinutes=(d=day())=>state.focus.filter(f=>f.date===d).reduce((a,f)=>a+f.minutes,0);
const levelFromXP=xp=>{let n=1;while(n<150&&Math.floor(100*Math.pow(n,1.6))<=xp)n++;const prev=Math.floor(100*Math.pow(n-1,1.6)),next=Math.floor(100*Math.pow(n,1.6));return {value:n,min:prev,max:next,progress:Math.max(0,Math.min(100,(xp-prev)/(next-prev)*100)),current:xp-prev,needed:next-prev}};
const level=()=>levelFromXP(state.xp);
const activityDays=()=>[...new Set([...state.ledger.map(x=>x.date),...state.journal.map(x=>x.date)].filter(Boolean))].sort().reverse();
function streaks(){const dates=activityDays();if(!dates.length)return {current:0,best:0};const set=new Set(dates);let cur=0,start=set.has(day())?0:-1;for(let i=start;set.has(dateOffset(i));i--)cur++;let best=0,run=0,prev=null;for(const ds of [...dates].sort()){if(prev){const date=new Date(prev+'T12:00:00');date.setDate(date.getDate()+1);run=day(date)===ds?run+1:1}else run=1;best=Math.max(best,run);prev=ds}return {current:cur,best}}
const bestStreak=()=>streaks().best;
function rewardXP(kind,refId,title,xp,coins){const old=level().value;state.xp+=xp;state.coins+=coins;state.ledger.push({id:uid(),kind,refId,title,xp,coins,date:day(),timestamp:Date.now()});store();if(level().value>old){confetti();toast(`¡SUBISTE AL NIVEL ${level().value}! ✨ +${xp} XP`,'success')}else toast(`+${xp} XP · +${coins} monedas. ¡Bien hecho! ✨`,'success');}
function toast(text,type=''){const t=document.createElement('div');t.className='toast '+type;t.textContent=text;$('#toast-region').append(t);setTimeout(()=>t.remove(),4400)}
function confetti(){const layer=$('#celebration-layer');for(let i=0;i<33;i++){const c=document.createElement('i');c.className='confetti';c.style.cssText=`--x:${Math.random()*100}vw;--color:${['#bba1ff','#70e3d3','#f7cc7e','#f78fb9'][i%4]};--delay:${Math.random()*.5}s;--shift:${Math.random()*160-80}px;--rotate:${Math.random()*360}deg`;layer.append(c);setTimeout(()=>c.remove(),2300)}}
const questDone=q=>q.repeat==='one'?Boolean(q.completedAt):q.doneDates?.includes(q.repeat==='daily'?day():weekKey());
const questToken=q=>q.repeat==='daily'?day():q.repeat==='weekly'?weekKey():'one';
const questXP=q=>(difficulty[q.difficulty]||difficulty.easy).xp;
function finishQuest(id){const q=state.quests.find(x=>x.id===id);if(!q)return;if(questDone(q)){toast('Esta misión ya está completada. ¡Bien hecho!');return}if(q.repeat==='one')q.completedAt=day();else{q.doneDates=q.doneDates||[];q.doneDates.push(questToken(q))}const d=difficulty[q.difficulty]||difficulty.easy;rewardXP('quest',q.id,q.title,d.xp,d.coins);render();}
const habitDue=h=>h.schedule==='all'||h.schedule==='weekdays'&&![0,6].includes(new Date().getDay())||h.schedule==='weekends'&&[0,6].includes(new Date().getDay());
function finishHabit(id){const h=state.habits.find(x=>x.id===id);if(!h)return;if(!habitDue(h)){toast('Este hábito está programado para otros días. ¡Disfrutá tu descanso!');return}if(h.history?.includes(day())){toast('¡Este hábito ya lo completaste hoy!');return}h.history=h.history||[];h.history.push(day());rewardXP('habit',h.id,h.title,15,6);render();}
const claimToken=c=>c.id+'@'+(c.period==='daily'?day():weekKey());
function claimChallenge(id){const c=challenges.find(x=>x.id===id);if(!c||state.claims.includes(claimToken(c))||c.current()<c.max)return;state.claims.push(claimToken(c));rewardXP('challenge',c.id,c.title,c.xp,c.coins);confetti();render();}
function redeemReward(id){const r=state.rewards.find(x=>x.id===id);if(!r)return;if(r.cost>state.coins){toast('Te faltan monedas. ¡Seguí sumando XP!','error');return}if(!confirm(`¿Canjear "${r.title}" por ${r.cost} monedas?`))return;state.coins-=r.cost;state.redemptions.push({id:uid(),rewardId:r.id,title:r.title,cost:r.cost,date:day()});store();confetti();toast(`¡Recompensa desbloqueada! ${r.icon}`,'success');render();}
function sectionHead(eyebrow,title,sub,button){return `<div class="page-header"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-subtitle">${sub}</p></div>${button||''}</div>`}
function button(text,action,klass='btn-primary',id=''){return `<button class="btn ${klass}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${text}</button>`}
const catIcon=c=>(categories[c]||categories.otro).icon;
function miniQuest(q){const done=questDone(q),d=difficulty[q.difficulty]||difficulty.easy;return `<div class="quest-row ${done?'completed':''}"><button class="quest-check ${done?'done':''}" data-action="finish-quest" data-id="${q.id}" title="${done?'Completada':'Marcar completada'}">${done?'✓':''}</button><div class="row-icon">${catIcon(q.category)}</div><div class="row-body"><div class="row-name">${esc(q.title)}</div><div class="row-sub">${q.repeat==='daily'?'↻ Diaria':q.repeat==='weekly'?'↻ Semanal':'◇ Única'} · ${d.name}${q.dueDate?' · '+fmtDate(q.dueDate):''}</div></div><span class="row-reward">+${d.xp} XP</span><div class="row-actions"><button class="tiny-action" data-action="edit-quest" data-id="${q.id}" title="Editar misión">✎</button><button class="tiny-action" data-action="remove-quest" data-id="${q.id}" title="Eliminar misión">×</button></div></div>`}
function miniHabit(h,showWeek=true){const done=(h.history||[]).includes(day()),due=habitDue(h);const start=new Date();start.setDate(start.getDate()-(start.getDay()+6)%7);const w=Array.from({length:7},(_,i)=>{const a=new Date(start);a.setDate(a.getDate()+i);return day(a)});return `<div class="habit-row"><div class="row-icon">${catIcon(h.category)}</div><div class="row-body"><div class="row-name">${esc(h.title)}</div><div class="row-sub">${h.schedule==='all'?'Todos los días':h.schedule==='weekdays'?'Lunes a viernes':'Fines de semana'} · ${(h.history||[]).length} registros</div>${showWeek?`<div class="week-head">${weekdays.map(w=>`<span>${w}</span>`).join('')}</div><div class="habit-track">${w.map(d=>`<span class="habit-day ${(h.history||[]).includes(d)?'hit':''}" title="${d}">${(h.history||[]).includes(d)?'✓':'·'}</span>`).join('')}</div>`:''}</div><button class="btn btn-sm ${done?'btn-success':'btn-secondary'} habit-check" data-action="finish-habit" data-id="${h.id}" ${!due&&!done?'disabled':''}>${done?'✓ Hecho':!due?'Descanso':'+15 XP'}</button><button class="tiny-action" data-action="edit-habit" data-id="${h.id}" title="Editar">✎</button><button class="tiny-action" data-action="remove-habit" data-id="${h.id}" title="Eliminar">×</button></div>`}
function levelCard(){const l=level();return `<div class="card"><div class="card-title-row"><h2 class="section-title">Tu progreso</h2><span class="pill">✨ Nivel ${l.value}</span></div><div class="level-box"><div class="level-ring" style="background:conic-gradient(#a88afc ${l.progress}%,#343954 ${l.progress}%)"><div class="level-ring-content"><strong>${l.value}</strong><small>NIVEL</small></div></div><div class="level-info"><h3>${l.value<4?'Explorador novato':l.value<8?'Aventurero decidido':l.value<15?'Héroe constante':'Leyenda de la vida'}</h3><p>¡Cada misión cuenta para tu próxima evolución!</p><div class="progress"><div style="width:${l.progress}%"></div></div><div class="progress-label"><span>${l.current} XP</span><span>${l.needed} XP siguiente nivel</span></div></div></div></div>`}
function dashboard(){const l=level(),st=streaks(),completed=dailyCount('quest'),hab=dailyCount('habit'),x=todayXP(),goal=Math.max(10,Number(state.profile.dailyGoal)||100),q=state.quests.filter(a=>!questDone(a)).slice(0,4),hs=state.habits.slice(0,3);return `${sectionHead('PANEL DE AVENTURA',`Hola, <span class="gradient-word">${esc(state.profile.name)}.</span> 👋`,'El siguiente nivel se construye con lo que hacés hoy.',button('＋ Nueva misión','open-quest'))}<div class="hero"><div class="hero-copy"><div class="hero-label">✦ EL MUNDO ES TUYO</div><h1>Tu vida. Tus reglas.<br><span class="gradient-word">Tu próxima victoria.</span></h1><p>No necesitás hacerlo perfecto. Solo avanzá un poco más que ayer. Hoy es otra oportunidad de subir de nivel.</p>${button('⚔️ ¡A completar misiones!','goto-quests')}</div><div class="hero-orb"></div><span class="hero-mascot">${esc(state.profile.avatar)}</span></div><div class="grid grid-4"><div class="card stat-card"><div class="stat-icon purple">⚡</div><div><div class="stat-label">XP total</div><div class="stat-value">${state.xp.toLocaleString('es-CR')}</div><div class="stat-hint">Nivel ${l.value}</div></div></div><div class="card stat-card"><div class="stat-icon teal">✓</div><div><div class="stat-label">Misiones hoy</div><div class="stat-value">${completed}</div><div class="stat-hint">${count('quest')} completadas en total</div></div></div><div class="card stat-card"><div class="stat-icon pink">🔥</div><div><div class="stat-label">Racha actual</div><div class="stat-value">${st.current} <span style="font-size:13px">días</span></div><div class="stat-hint">Récord: ${st.best} días</div></div></div><div class="card stat-card"><div class="stat-icon amber">◈</div><div><div class="stat-label">Monedas</div><div class="stat-value">${state.coins.toLocaleString('es-CR')}</div><div class="stat-hint">Recompensas por ganar</div></div></div></div><div class="grid grid-2 mt-24"><div>${levelCard()}<div class="card mt-24"><div class="card-title-row"><h2 class="section-title">⚔️ Misiones pendientes</h2><button class="inline-link" data-action="goto-quests">VER TODAS →</button></div>${q.length?q.map(miniQuest).join(''):`<div class="empty"><span class="empty-emoji">🏆</span>¡Sin pendientes! Creá una nueva misión.</div>`}${button('＋ Añadir una misión','open-quest','btn-secondary')}</div></div><div><div class="card"><div class="card-title-row"><h2 class="section-title">🎯 Objetivo de hoy</h2><span class="pill teal">${Math.min(100,Math.round(x/goal*100))}%</span></div><div style="font:700 30px 'Space Grotesk';margin-bottom:12px">${x}<span style="font-size:13px;color:var(--muted)"> / ${goal} XP</span></div><div class="progress"><div style="width:${Math.min(100,x/goal*100)}%"></div></div><p class="section-desc">${x>=goal?'¡Meta del día alcanzada! Una gran victoria. 🎉':`Te faltan ${goal-x} XP para cumplir tu meta diaria.`}</p></div><div class="card mt-24"><div class="card-title-row"><h2 class="section-title">🌿 Hábitos de hoy</h2><button class="inline-link" data-action="goto-habits">VER TODOS →</button></div>${hs.length?hs.map(h=>miniHabit(h,false)).join(''):`<div class="empty">Creá tu primer hábito.</div>`}<div class="section-desc mt-16">${hab} hábito${hab===1?'':'s'} completado${hab===1?'':'s'} hoy.</div></div></div></div><div class="grid grid-2 mt-24"><div class="card"><div class="card-title-row"><h2 class="section-title">✧ Desafíos activos</h2><button class="inline-link" data-action="goto-challenges">VER TODOS →</button></div>${challenges.slice(0,3).map(challengeRow).join('')}</div><div class="card"><div class="card-title-row"><h2 class="section-title">📊 Tus últimos 7 días</h2><button class="inline-link" data-action="goto-analytics">ESTADÍSTICAS →</button></div>${weeklyChart()}<p class="section-desc mt-16">Sumá XP cada día y construí una racha legendaria.</p></div></div>`}
function challengeRow(c){const val=c.current(),claimed=state.claims.includes(claimToken(c));return `<div class="challenge"><div class="challenge-icon">${c.icon}</div><div class="challenge-main"><b>${c.title}</b><small>${c.desc} · +${c.xp} XP · ◈ ${c.coins}</small><div class="progress"><div style="width:${Math.min(100,val/c.max*100)}%"></div></div><div class="progress-label"><span>${Math.min(val,c.max)} / ${c.max}</span><span>${c.period==='daily'?'Diario':'Semanal'}</span></div></div>${claimed?'<span class="pill teal">✓ Cobrado</span>':val>=c.max?button('Cobrar','claim-challenge','btn-success btn-sm',c.id):'<span class="pill">En curso</span>'}</div>`}
function questsPage(){let qs=state.quests.filter(q=>ui.questFilter==='all'||(ui.questFilter==='todo'&&!questDone(q))||(ui.questFilter==='done'&&questDone(q))||ui.questFilter===q.repeat).sort((a,b)=>Number(questDone(a))-Number(questDone(b)));return `${sectionHead('TUS MISIONES','⚔️ Tablero de misiones','Definí tus objetivos y ganá experiencia real cada vez que avanzás.',button('＋ Nueva misión','open-quest'))}<div class="grid grid-3"><div class="card stat-card"><div class="stat-icon purple">⚔️</div><div><div class="stat-label">Misiones creadas</div><div class="stat-value">${state.quests.length}</div></div></div><div class="card stat-card"><div class="stat-icon teal">✓</div><div><div class="stat-label">Completadas hoy</div><div class="stat-value">${dailyCount('quest')}</div></div></div><div class="card stat-card"><div class="stat-icon amber">⚡</div><div><div class="stat-label">Ganadas en total</div><div class="stat-value">${count('quest')}</div></div></div></div><div class="card mt-24"><div class="card-title-row wrap"><h2 class="section-title">Tu lista de aventuras</h2><div class="segment">${[['all','Todas'],['todo','Pendientes'],['done','Hechas'],['daily','Diarias']].map(([id,t])=>`<button data-action="quest-filter" data-value="${id}" class="${ui.questFilter===id?'active':''}">${t}</button>`).join('')}</div></div>${qs.length?qs.map(miniQuest).join(''):`<div class="empty"><span class="empty-emoji">🗺️</span>No hay misiones en esta sección.</div>`}</div><div class="card mt-24"><h2 class="section-title">🧩 ¿Cómo se ganan puntos?</h2><p class="section-desc">Misión fácil: 20 XP y 8 monedas · Normal: 40 XP y 15 monedas · Épica: 75 XP y 30 monedas. Las misiones diarias se pueden volver a completar al día siguiente y las semanales cada lunes.</p></div>`}
function habitsPage(){const hs=state.habits;return `${sectionHead('LA MAGIA DE LA CONSTANCIA','🌿 Mis hábitos','Repetí pequeñas acciones y construí resultados enormes.',button('＋ Nuevo hábito','open-habit'))}<div class="grid grid-3"><div class="card stat-card"><div class="stat-icon teal">🌿</div><div><div class="stat-label">Hábitos activos</div><div class="stat-value">${hs.length}</div></div></div><div class="card stat-card"><div class="stat-icon purple">✓</div><div><div class="stat-label">Registros hoy</div><div class="stat-value">${dailyCount('habit')}</div></div></div><div class="card stat-card"><div class="stat-icon pink">🔥</div><div><div class="stat-label">Racha de actividad</div><div class="stat-value">${streaks().current} días</div></div></div></div><div class="card mt-24"><div class="card-title-row"><h2 class="section-title">Esta semana</h2><span class="pill teal">+15 XP por hábito</span></div>${hs.length?hs.map(h=>miniHabit(h)).join(''):`<div class="empty"><span class="empty-emoji">🌱</span>Tu primer hábito está a un clic de distancia.</div>`}</div><div class="card mt-24"><h2 class="section-title">💜 Lo que importa es volver</h2><p class="section-desc">No pasa nada si un día descansás. La racha es una herramienta para motivarte, no una forma de castigarte. Podés adaptar tus hábitos cuando cambien tus prioridades.</p></div>`}
function focusPage(){return `${sectionHead('CONCENTRACIÓN REAL','🧠 Modo enfoque','Un espacio sin distracciones para avanzar en lo que importa.')}<div class="grid grid-2"><div class="card" style="text-align:center"><div class="eyebrow" style="margin-top:4px">TU TIEMPO ES VALIOSO</div><div class="focus-clock" id="focus-clock" style="--pct:0%"><div class="focus-clock-inner"><div class="time" id="focus-time">${clock(ui.focusRemaining)}</div><small>${ui.focusRunning?'EN PROGRESO':'LISTO PARA EMPEZAR'}</small></div></div><div class="segment" style="margin:auto">${[15,25,45,60].map(n=>`<button data-action="focus-duration" data-value="${n}" class="${ui.focusLength===n?'active':''}" ${ui.focusRunning?'disabled':''}>${n} min</button>`).join('')}</div><div style="margin:22px auto;max-width:310px"><label class="section-desc" for="focus-task" style="display:block;margin-bottom:8px">¿En qué vas a concentrarte?</label><select class="input" id="focus-task"><option value="">Mi concentración personal</option>${state.quests.filter(q=>!questDone(q)).map(q=>`<option value="${q.id}" ${ui.focusTask===q.id?'selected':''}>${esc(q.title)}</option>`).join('')}</select></div><div class="flex align-center wrap" style="justify-content:center;gap:9px">${ui.focusRunning?button('⏸ Pausar sesión','pause-focus','btn-secondary'):button(ui.focusPausedAt?'▶ Reanudar':'▶ Empezar a enfocarme','start-focus')}${button('↺ Reiniciar','reset-focus','btn-secondary')}</div><p class="section-desc" style="margin:15px 0 0">Ganás 2 XP y 1 moneda por cada minuto completado de enfoque.</p></div><div><div class="grid grid-2"><div class="card stat-card"><div class="stat-icon purple">◎</div><div><div class="stat-label">Minutos hoy</div><div class="stat-value">${dailyMinutes()}</div></div></div><div class="card stat-card"><div class="stat-icon teal">⌛</div><div><div class="stat-label">Sesiones totales</div><div class="stat-value">${state.focus.length}</div></div></div></div><div class="card mt-24"><div class="card-title-row"><h2 class="section-title">✨ Tus sesiones recientes</h2></div>${state.focus.length?[...state.focus].reverse().slice(0,8).map(s=>`<div class="stat-row"><span>${fmtDate(s.date)} · ${esc(s.title||'Concentración personal')}</span><b>${s.minutes} min</b></div>`).join(''):`<div class="empty"><span class="empty-emoji">🧠</span>Tu primera sesión puede comenzar hoy.</div>`}</div><div class="card mt-24"><h2 class="section-title">☕ Consejo para concentrarte</h2><p class="section-desc">Elegí una misión, silenciá notificaciones y concentrate durante el tiempo seleccionado. Si pausás, se conserva el tiempo restante en este dispositivo.</p></div></div></div>`}
function challengesPage(){return `${sectionHead('MISIONES ESPECIALES','✧ Desafíos y bonificaciones','Completá objetivos especiales para ganar XP extra y monedas.')}<div class="grid grid-2"><div class="card"><h2 class="section-title">☀️ Desafíos de hoy</h2><p class="section-desc">Se renuevan cada día.</p>${challenges.filter(c=>c.period==='daily').map(challengeRow).join('')}</div><div class="card"><h2 class="section-title">🌙 Desafíos semanales</h2><p class="section-desc">Un nuevo comienzo cada lunes.</p>${challenges.filter(c=>c.period==='weekly').map(challengeRow).join('')}<div class="divide-line"></div><div class="feature-card"><div class="feature-icon">🏆</div><div><b>Tu progreso es tuyo</b><p class="section-desc mb-0">Si cumplís un desafío, recordá cobrar tu premio.</p></div></div></div></div>`}
function shopPage(){return `${sectionHead('DISFRUTÁ TUS VICTORIAS','◇ Tienda de recompensas','Tus logros también merecen diversión. Creá recompensas reales para vos.',button('＋ Nueva recompensa','open-reward'))}<div class="card" style="margin-bottom:22px;background:linear-gradient(120deg,#55406f,#282b51);border-color:#755f91"><div class="flex align-center justify-between wrap gap-12"><div><div class="eyebrow">TU SALDO DISPONIBLE</div><div style="font:700 40px 'Space Grotesk'">◈ ${state.coins.toLocaleString('es-CR')}</div><p class="section-desc">Las monedas se ganan con misiones, hábitos y desafíos.</p></div><div style="font-size:65px">💎</div></div></div><div class="grid grid-3">${state.rewards.map(r=>`<div class="card"><div class="flex justify-between align-center"><div class="shop-icon">${esc(r.icon||'🎁')}</div><span class="pill gold">◈ ${r.cost}</span></div><h3 class="section-title mt-24">${esc(r.title)}</h3><p class="section-desc">Una recompensa para disfrutar tu avance.</p><div class="flex gap-8 mt-24">${button('Canjear','redeem','btn-primary',r.id).replace('<button ','<button '+(state.coins<r.cost?'disabled ':''))}<button class="tiny-action" data-action="edit-reward" data-id="${r.id}" title="Editar">✎</button><button class="tiny-action" data-action="remove-reward" data-id="${r.id}" title="Eliminar">×</button></div></div>`).join('')||'<div class="card empty">Creá tu primera recompensa.</div>'}</div><div class="card mt-24"><div class="card-title-row"><h2 class="section-title">🎁 Historial de premios</h2></div>${state.redemptions.length?[...state.redemptions].reverse().slice(0,8).map(r=>`<div class="stat-row"><span>${esc(r.title)} · ${fmtDate(r.date)}</span><b>◈ −${r.cost}</b></div>`).join(''):'<div class="empty">¡Todavía no canjeaste premios!</div>'}</div>`}
function achievementsPage(){const unlocked=achievements.filter(a=>a.ok()).length;return `${sectionHead('TU SALÓN DE LA FAMA','♛ Mis logros','Las victorias más memorables de tu aventura.')}<div class="card" style="margin-bottom:23px"><div class="flex justify-between align-center gap-12"><div><h2 class="section-title">${unlocked} de ${achievements.length} insignias</h2><p class="section-desc">Cada logro cuenta una parte de tu historia.</p></div><span style="font-size:46px">🏆</span></div><div class="progress"><div style="width:${unlocked/achievements.length*100}%"></div></div></div><div class="badge-grid">${achievements.map(a=>`<div class="achievement ${a.ok()?'':'locked'}"><span class="achievement-icon">${a.ok()?a.icon:'🔒'}</span><b>${esc(a.title)}</b><small>${esc(a.desc)}</small>${a.ok()?'<span class="pill teal" style="display:inline-block;margin-top:11px">✓ DESBLOQUEADO</span>':''}</div>`).join('')}</div>`}
function weeklyChart(kind='xp'){const dates=Array.from({length:7},(_,i)=>dateOffset(i-6));const vals=dates.map(d=>kind==='xp'?state.ledger.filter(e=>e.date===d).reduce((a,e)=>a+e.xp,0):kind==='quests'?dailyCount('quest',d):dailyMinutes(d));const mx=Math.max(1,...vals);return `<div class="metric-bars">${vals.map((n,i)=>`<div class="metric-col"><div class="metric-bar ${kind==='quests'?'teal':''}" style="height:${n?Math.max(6,n/mx*94):2}%"><small>${n||''}</small></div></div>`).join('')}</div><div class="metric-labels">${dates.map(d=>`<span>${new Date(d+'T12:00').toLocaleDateString('es-CR',{weekday:'short'}).replace('.','')}</span>`).join('')}</div>`}
function analyticsPage(){const last7=Array.from({length:7},(_,i)=>dateOffset(i-6)),total=last7.reduce((a,d)=>a+state.ledger.filter(e=>e.date===d).reduce((v,e)=>v+e.xp,0),0);return `${sectionHead('TUS NÚMEROS','▥ Estadísticas y progreso','Tus avances, sin compararte con nadie más.')}<div class="grid grid-4"><div class="card stat-card"><div class="stat-icon purple">⚡</div><div><div class="stat-label">XP esta semana</div><div class="stat-value">${total}</div></div></div><div class="card stat-card"><div class="stat-icon teal">⚔️</div><div><div class="stat-label">Misiones totales</div><div class="stat-value">${count('quest')}</div></div></div><div class="card stat-card"><div class="stat-icon pink">🌱</div><div><div class="stat-label">Hábitos logrados</div><div class="stat-value">${count('habit')}</div></div></div><div class="card stat-card"><div class="stat-icon amber">🧠</div><div><div class="stat-label">Minutos de enfoque</div><div class="stat-value">${state.focus.reduce((a,f)=>a+f.minutes,0)}</div></div></div></div><div class="grid grid-2 mt-24"><div class="card"><h2 class="section-title">⚡ XP de los últimos 7 días</h2><p class="section-desc">Tu energía invertida en crecer.</p>${weeklyChart('xp')}</div><div class="card"><h2 class="section-title">⚔️ Misiones por día</h2><p class="section-desc">Cada pequeña victoria suma.</p>${weeklyChart('quests')}</div></div><div class="grid grid-2 mt-24"><div class="card"><h2 class="section-title">🏅 Récords personales</h2>${[['Nivel actual',level().value],['Racha actual',streaks().current+' días'],['Mayor racha',bestStreak()+' días'],['Logros desbloqueados',achievements.filter(a=>a.ok()).length+'/'+achievements.length],['Recompensas canjeadas',state.redemptions.length],['Entradas en el diario',state.journal.length]].map(([k,v])=>`<div class="stat-row"><span>${k}</span><b>${v}</b></div>`).join('')}</div><div class="card"><h2 class="section-title">🧭 Tus últimas victorias</h2>${state.ledger.length?[...state.ledger].reverse().slice(0,7).map(e=>`<div class="stat-row"><span>${esc(e.title)} · ${fmtDate(e.date)}</span><b>+${e.xp} XP</b></div>`).join(''):'<div class="empty">¡Completá una misión para empezar!</div>'}</div></div>`}
function calendarPage(){const current=new Date(),dt=new Date(current.getFullYear(),current.getMonth()+ui.calOffset,1),year=dt.getFullYear(),month=dt.getMonth(),start=(dt.getDay()+6)%7,days=new Date(year,month+1,0).getDate(),cells=Array.from({length:start},()=>'<span></span>');for(let n=1;n<=days;n++){const d=day(new Date(year,month,n)),active=state.ledger.some(x=>x.date===d)||state.journal.some(x=>x.date===d);cells.push(`<button class="calendar-cell ${d===day()?'today':''} ${active?'active':''}" data-action="select-calendar" data-value="${d}" style="${ui.selectedDate===d?'background:#514882;color:white':''}">${n}</button>`)}const dtlogs=state.ledger.filter(e=>e.date===ui.selectedDate),entry=state.journal.find(e=>e.date===ui.selectedDate);return `${sectionHead('TU HISTORIA EN EL TIEMPO','▦ Calendario de progreso','Reviví lo que construiste, un día a la vez.')}<div class="grid grid-2"><div class="card"><div class="card-title-row"><button class="btn btn-secondary btn-sm" data-action="prev-month">←</button><h2 class="section-title" style="text-transform:capitalize">${dt.toLocaleDateString('es-CR',{month:'long',year:'numeric'})}</h2><button class="btn btn-secondary btn-sm" data-action="next-month">→</button></div><div class="calendar-grid">${weekdays.map(w=>`<div class="calendar-day-header">${w}</div>`).join('')}${cells.join('')}</div><p class="section-desc mt-24">Los puntos turquesa indican actividad registrada.</p></div><div class="card"><div class="eyebrow">DÍA SELECCIONADO</div><h2 class="section-title">${fmtDate(ui.selectedDate,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</h2><div class="divide-line"></div>${dtlogs.length?dtlogs.map(e=>`<div class="stat-row"><span>${esc(e.title)}</span><b>+${e.xp} XP</b></div>`).join(''):'<div class="empty">Sin misiones registradas ese día.</div>'}${entry?`<div class="journal-entry"><b>📝 Tu diario</b><p>${esc(entry.text)}</p></div>`:''}</div></div>`}
function journalPage(){const todays=state.journal.find(e=>e.date===day());return `${sectionHead('UN ESPACIO PARA VOS','✎ Mi diario personal','Anotá tus pensamientos, aprendizajes y pequeñas victorias.')}<div class="grid grid-2"><div class="card"><div class="eyebrow">${fmtDate(day(),{weekday:'long',day:'numeric',month:'long',year:'numeric'}).toUpperCase()}</div><h2 class="section-title">¿Cómo te sentís hoy?</h2><div class="flex wrap gap-8 mt-16" id="mood-choices">${[['😄','Genial'],['🙂','Bien'],['😐','Normal'],['😔','Bajo'],['😣','Difícil']].map(([e,name])=>`<button class="mood-button ${todays?.mood===e?'selected':''}" data-action="set-mood" data-value="${e}" title="${name}">${e}</button>`).join('')}</div><div class="field mt-24"><label for="journal-text">Tu entrada de hoy</label><textarea class="input" id="journal-text" rows="9" placeholder="Hoy avancé en... Me sentí... Mañana quiero...">${esc(todays?.text||'')}</textarea></div>${button('💾 Guardar reflexión','save-journal')}<p class="section-desc">Tu diario se guarda únicamente en este dispositivo. Exportá respaldos en Ajustes.</p></div><div class="card"><div class="card-title-row"><h2 class="section-title">📖 Entradas anteriores</h2><span class="pill">${state.journal.length} entradas</span></div>${state.journal.length?[...state.journal].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<div class="journal-entry"><div class="flex justify-between align-center"><div class="entry-date">${fmtDate(e.date,{weekday:'long',day:'numeric',month:'long'})} · ${e.mood||'📝'}</div><button class="tiny-action" data-action="delete-journal" data-value="${e.date}" title="Eliminar esta entrada">×</button></div><p>${esc(e.text)}</p></div>`).join(''):'<div class="empty"><span class="empty-emoji">💭</span>Tu historia empieza con una palabra.</div>'}</div></div>`}
function settingsPage(){return `${sectionHead('TU MUNDO, TUS REGLAS','⚙️ Ajustes personales','Personalizá tu experiencia y conservá el control de tus datos.')}<div class="grid grid-2"><div class="card"><h2 class="section-title">👤 Tu personaje</h2><form id="settings-form" class="mt-24"><div class="field"><label for="profile-name">Nombre de jugador</label><input class="input" id="profile-name" name="name" maxlength="36" value="${esc(state.profile.name)}" required></div><div class="field"><label>Elegí tu avatar</label><div class="category-chips" id="avatar-picker">${['⚡','👑','🚀','🦁','🧙','🛡️','🐉','🌟'].map(a=>`<button type="button" class="chip ${state.profile.avatar===a?'selected':''}" data-action="pick-avatar" data-value="${a}" style="font-size:21px">${a}</button>`).join('')}</div></div><div class="field"><label for="daily-goal">Meta diaria de XP</label><input class="input" id="daily-goal" name="goal" type="number" min="20" max="2000" step="10" value="${state.profile.dailyGoal}"></div><button class="btn btn-primary" type="submit">Guardar perfil</button></form></div><div class="card"><h2 class="section-title">🔐 Privacidad y respaldos</h2><p class="section-desc">Toda tu información queda en el dispositivo. No hace falta registrarte, ni subir tus datos a una cuenta. No hay anuncios ni seguimiento.</p><div class="grid mt-24">${button('⬇ Exportar respaldo JSON','export-backup','btn-secondary')}${button('⬆ Importar un respaldo','import-backup','btn-secondary')}<input type="file" accept=".json,application/json" id="backup-file" style="display:none">${button('🗑 Borrar todos mis datos','reset-data','btn-danger')}</div><p class="section-desc">Importar un respaldo reemplaza los datos existentes de este dispositivo. Guardá primero una copia.</p></div></div><div class="card mt-24"><div class="flex align-center justify-between wrap gap-8"><div><h2 class="section-title">💜 LevelUp Life 1.0</h2><p class="section-desc mb-0">Un juego para crecer a tu ritmo. Hecho para uso personal, sin suscripciones.</p></div><span class="pill teal">Sin conexión y privado</span></div></div>`}
function render(){let view=ui.view;const pages={dashboard,quests:questsPage,habits:habitsPage,focus:focusPage,challenges:challengesPage,shop:shopPage,achievements:achievementsPage,analytics:analyticsPage,calendar:calendarPage,journal:journalPage,settings:settingsPage};const fn=pages[view]||dashboard;$('#page').innerHTML=`<div class="fade-in">${fn()}</div>`;$('#breadcrumb').innerHTML=`<span class="crumb-muted">TU AVENTURA</span><span class="crumb-arrow">/</span><b>${esc((nav.find(n=>n[0]===view)||nav[0])[2])}</b>`;$('#top-coins').textContent='◈ '+state.coins.toLocaleString('es-CR');$('#profile-button').textContent=state.profile.avatar;$('#live-date').textContent=new Date().toLocaleDateString('es-CR',{weekday:'long',day:'numeric',month:'short'});$('#side-nav').innerHTML=nav.map(([v,i,t])=>`<button data-action="nav" data-value="${v}" class="nav-link ${view===v?'active':''}"><span class="nav-icon">${i}</span><span>${t}</span></button>`).join('');$('#bottom-nav').innerHTML=[...nav.slice(0,4),['more','☷','Más']].map(([v,i,t])=>`<button data-action="${v==='more'?'open-more':'nav'}" data-value="${v}" class="bottom-link ${view===v?'active':''}"><span class="nav-icon">${i}</span><span>${t}</span></button>`).join('');updateClockUI()}
const goto=v=>{ui.view=v;$('#sidebar').classList.remove('open');$('#side-backdrop').classList.remove('visible');render();window.scrollTo({top:0,behavior:'smooth'})};
const formField=(label,code)=>`<div class="field"><label>${label}</label>${code}</div>`;
function modal(title,content){$('#modal-root').innerHTML=`<div class="modal-screen" id="modal-screen"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Cerrar">✕</button></div>${content}</div></div>`;$('.modal input:not([type=hidden])')?.focus()}
const closeModal=()=>{$('#modal-root').innerHTML=''};
function questModal(id){const q=state.quests.find(x=>x.id===id)||{};modal(id?'Editar misión':'Nueva misión',`<form id="quest-form"><input type="hidden" name="id" value="${esc(q.id||'')}">${formField('Nombre de la misión *',`<input name="title" class="input" maxlength="90" required placeholder="Ej: Leer durante 20 minutos" value="${esc(q.title||'')}">`)}${formField('Descripción (opcional)',`<textarea name="description" class="input" rows="2" maxlength="280" placeholder="¿Qué querés lograr?">${esc(q.description||'')}</textarea>`)}<div class="form-grid">${formField('Categoría',`<select name="category" class="input">${Object.entries(categories).map(([k,c])=>`<option value="${k}" ${q.category===k?'selected':''}>${c.icon} ${c.title}</option>`).join('')}</select>`)}${formField('Dificultad',`<select name="difficulty" class="input">${Object.entries(difficulty).map(([k,d])=>`<option value="${k}" ${q.difficulty===(k)||(!q.difficulty&&k==='medium')?'selected':''}>${d.name} · ${d.xp} XP</option>`).join('')}</select>`)}</div><div class="form-grid">${formField('Frecuencia',`<select name="repeat" class="input"><option value="one" ${q.repeat==='one'?'selected':''}>Una sola vez</option><option value="daily" ${q.repeat==='daily'?'selected':''}>Cada día</option><option value="weekly" ${q.repeat==='weekly'?'selected':''}>Cada semana</option></select>`)}${formField('Fecha límite (opcional)',`<input type="date" name="dueDate" class="input" value="${esc(q.dueDate||'')}">`)}</div><div class="modal-footer">${button('Cancelar','close-modal','btn-secondary')}<button class="btn btn-primary" type="submit">${id?'Guardar cambios':'Crear misión'}</button></div></form>`)}
function habitModal(id){const h=state.habits.find(x=>x.id===id)||{};modal(id?'Editar hábito':'Nuevo hábito',`<form id="habit-form"><input type="hidden" name="id" value="${esc(h.id||'')}">${formField('Nombre del hábito *',`<input name="title" class="input" maxlength="80" required placeholder="Ej: Leer 10 minutos" value="${esc(h.title||'')}">`)}${formField('Categoría',`<select name="category" class="input">${Object.entries(categories).map(([k,c])=>`<option value="${k}" ${h.category===k?'selected':''}>${c.icon} ${c.title}</option>`).join('')}</select>`)}${formField('¿Cuándo querés cumplirlo?',`<select name="schedule" class="input"><option value="all" ${h.schedule==='all'?'selected':''}>Todos los días</option><option value="weekdays" ${h.schedule==='weekdays'?'selected':''}>Lunes a viernes</option><option value="weekends" ${h.schedule==='weekends'?'selected':''}>Fines de semana</option></select>`)}<div class="modal-footer">${button('Cancelar','close-modal','btn-secondary')}<button class="btn btn-primary" type="submit">Guardar hábito</button></div></form>`)}
function rewardModal(id){const r=state.rewards.find(x=>x.id===id)||{};modal(id?'Editar recompensa':'Nueva recompensa',`<form id="reward-form"><input type="hidden" name="id" value="${esc(r.id||'')}">${formField('Recompensa *',`<input name="title" class="input" maxlength="75" required placeholder="Ej: Tarde libre para jugar" value="${esc(r.title||'')}">`)}<div class="form-grid">${formField('Ícono (emoji)',`<input name="icon" class="input" maxlength="6" value="${esc(r.icon||'🎁')}">`)}${formField('Costo en monedas',`<input type="number" name="cost" min="1" max="99999" class="input" value="${r.cost||100}" required>`)}</div><div class="modal-footer">${button('Cancelar','close-modal','btn-secondary')}<button type="submit" class="btn btn-primary">Guardar recompensa</button></div></form>`)}
function saveJournal(){const txt=$('#journal-text')?.value.trim(),mood=document.querySelector('#mood-choices .selected')?.dataset.value||'🙂';if(!txt){toast('Escribí al menos una oración para guardar.','error');return}const existing=state.journal.find(e=>e.date===day());if(existing){existing.text=txt;existing.mood=mood}else state.journal.push({id:uid(),date:day(),text:txt,mood});store();toast('Reflexión guardada con cariño. 📝','success');render()}
function exportBackup(){const body=JSON.stringify({...state,exportedAt:new Date().toISOString(),app:'LevelUp Life'},null,2),name=`LevelUp-Life-Respaldo-${day()}.json`;if(window.LevelUpNative?.shareBackup){window.LevelUpNative.shareBackup(name,body).then(()=>toast('Respaldo listo para compartir.','success')).catch(()=>downloadBackup(name,body));return}downloadBackup(name,body)}
function downloadBackup(name,body){const blob=new Blob([body],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),6000);toast('Respaldo descargado. Guardalo en un lugar seguro.','success')}
function importBackup(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result);if(parsed.schema!==1||!Array.isArray(parsed.quests)||!Array.isArray(parsed.habits)||!Array.isArray(parsed.ledger))throw Error('Formato inválido');if(!confirm('¿Restaurar este respaldo y REEMPLAZAR los datos actuales?'))return;state={...seed(),...parsed};store();ui.view='dashboard';closeModal();render();toast('Respaldo restaurado correctamente. 💜','success')}catch(e){toast('No pudimos leer este respaldo de LevelUp Life.','error')}};reader.readAsText(file)}
const clock=sec=>`${String(Math.floor(Math.max(0,sec)/60)).padStart(2,'0')}:${String(Math.max(0,sec)%60).padStart(2,'0')}`;
function persistFocus(){try{sessionStorage.setItem(SESSION_KEY,JSON.stringify({running:ui.focusRunning,end:ui.focusEnd,remaining:ui.focusRemaining,length:ui.focusLength,task:ui.focusTask}))}catch{}}
function restoreFocus(){try{const x=JSON.parse(sessionStorage.getItem(SESSION_KEY)||'null');if(!x)return;ui.focusLength=[15,25,45,60].includes(x.length)?x.length:25;ui.focusTask=x.task||'';if(x.running&&Number.isFinite(x.end)){ui.focusRunning=true;ui.focusEnd=x.end;ui.focusRemaining=Math.max(0,Math.ceil((x.end-Date.now())/1000));}else ui.focusRemaining=Math.max(1,Math.min(ui.focusLength*60,x.remaining||ui.focusLength*60))}catch{}}
function updateClockUI(){const t=$('#focus-time');if(t)t.textContent=clock(ui.focusRemaining);const ring=$('#focus-clock');if(ring)ring.style.setProperty('--pct',(100*(1-ui.focusRemaining/(ui.focusLength*60)))+'%')}
function tick(){if(!ui.focusRunning)return;ui.focusRemaining=Math.max(0,Math.ceil((ui.focusEnd-Date.now())/1000));if(ui.focusRemaining<=0){ui.focusRunning=false;ui.focusRemaining=0;persistFocus();const mins=ui.focusLength;const title=state.quests.find(x=>x.id===ui.focusTask)?.title||'Concentración personal';state.focus.push({id:uid(),date:day(),minutes:mins,title});rewardXP('focus',uid(),'Sesión de enfoque · '+title,mins*2,mins);confetti();ui.focusRemaining=ui.focusLength*60;persistFocus();render();}else updateClockUI()}
restoreFocus();setInterval(tick,1000);
function action(name,el){const id=el.dataset.id,val=el.dataset.value;switch(name){case 'nav':goto(val);break;case 'goto-quests':goto('quests');break;case 'goto-habits':goto('habits');break;case 'goto-analytics':goto('analytics');break;case 'goto-challenges':goto('challenges');break;case 'open-more':$('#sidebar').classList.add('open');$('#side-backdrop').classList.add('visible');break;case 'close-modal':closeModal();break;case 'open-quest':questModal();break;case 'edit-quest':questModal(id);break;case 'finish-quest':finishQuest(id);break;case 'remove-quest':if(confirm('¿Eliminar esta misión? Los XP ya ganados permanecen en tu historial.')){state.quests=state.quests.filter(x=>x.id!==id);store();render()}break;case 'quest-filter':ui.questFilter=val;render();break;case 'open-habit':habitModal();break;case 'edit-habit':habitModal(id);break;case 'finish-habit':finishHabit(id);break;case 'remove-habit':if(confirm('¿Eliminar este hábito? El progreso ya ganado se conservará.')){state.habits=state.habits.filter(x=>x.id!==id);store();render()}break;case 'claim-challenge':claimChallenge(id);break;case 'redeem':redeemReward(id);break;case 'open-reward':rewardModal();break;case 'edit-reward':rewardModal(id);break;case 'remove-reward':if(confirm('¿Eliminar esta recompensa de la tienda?')){state.rewards=state.rewards.filter(x=>x.id!==id);store();render()}break;case 'focus-duration':if(ui.focusRunning)return;ui.focusLength=Number(val);ui.focusRemaining=ui.focusLength*60;ui.focusPausedAt=0;persistFocus();render();break;case 'start-focus':if(ui.focusRunning)return;ui.focusTask=$('#focus-task')?.value||ui.focusTask;ui.focusEnd=Date.now()+ui.focusRemaining*1000;ui.focusRunning=true;ui.focusPausedAt=0;persistFocus();render();break;case 'pause-focus':ui.focusRemaining=Math.max(0,Math.ceil((ui.focusEnd-Date.now())/1000));ui.focusRunning=false;ui.focusPausedAt=Date.now();persistFocus();render();break;case 'reset-focus':if(ui.focusRunning&&!confirm('¿Reiniciar la sesión actual?'))return;ui.focusRunning=false;ui.focusRemaining=ui.focusLength*60;ui.focusPausedAt=0;persistFocus();render();break;case 'prev-month':ui.calOffset--;render();break;case 'next-month':ui.calOffset++;render();break;case 'select-calendar':ui.selectedDate=val;render();break;case 'set-mood':document.querySelectorAll('#mood-choices .mood-button').forEach(x=>x.classList.toggle('selected',x.dataset.value===val));break;case 'save-journal':saveJournal();break;case 'delete-journal':if(confirm('¿Eliminar esta entrada del diario?')){state.journal=state.journal.filter(x=>x.date!==val);store();render()}break;case 'pick-avatar':document.querySelectorAll('#avatar-picker .chip').forEach(x=>x.classList.toggle('selected',x.dataset.value===val));state.profile.avatar=val;store();$('#profile-button').textContent=val;break;case 'export-backup':exportBackup();break;case 'import-backup':$('#backup-file')?.click();break;case 'reset-data':{const answer=prompt('Se borrarán todos tus datos guardados EN ESTE DISPOSITIVO. Para confirmar escribí BORRAR (antes exportá un respaldo).');if(answer==='BORRAR'){state=seed();store();ui.view='dashboard';render();toast('Datos restablecidos.','success')}break;}default:break}}
document.addEventListener('click',e=>{const x=e.target.closest('[data-action]');if(x){e.preventDefault();action(x.dataset.action,x)}});
document.addEventListener('submit',e=>{const form=e.target,formType=form.getAttribute('id');if(!['quest-form','habit-form','reward-form','settings-form'].includes(formType))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));if(formType==='quest-form'){const title=String(data.title||'').trim();if(!title)return;const q=state.quests.find(x=>x.id===data.id);const update={title,description:String(data.description||'').trim(),category:data.category||'otro',difficulty:data.difficulty||'easy',repeat:data.repeat||'one',dueDate:data.dueDate||''};if(q)Object.assign(q,update);else state.quests.push({id:uid(),...update,doneDates:[],createdAt:day()});toast(q?'Misión actualizada.':'¡Nueva misión añadida!','success')}
if(formType==='habit-form'){const title=String(data.title||'').trim();if(!title)return;const h=state.habits.find(x=>x.id===data.id),update={title,category:data.category||'otro',schedule:data.schedule||'all'};if(h)Object.assign(h,update);else state.habits.push({id:uid(),...update,history:[],createdAt:day()});toast('Hábito guardado.','success')}
if(formType==='reward-form'){const title=String(data.title||'').trim();if(!title)return;const r=state.rewards.find(x=>x.id===data.id),update={title,icon:String(data.icon||'🎁').trim().slice(0,6),cost:Math.max(1,Math.min(99999,Number(data.cost)||100))};if(r)Object.assign(r,update);else state.rewards.push({id:uid(),...update});toast('Recompensa guardada.','success')}
if(formType==='settings-form'){state.profile.name=String(data.name||'Aventurero').trim().slice(0,36)||'Aventurero';state.profile.dailyGoal=Math.max(20,Math.min(2000,Number(data.goal)||100));toast('¡Tu perfil quedó actualizado!','success')}
store();closeModal();render()});
document.addEventListener('change',e=>{if(e.target.id==='backup-file'){importBackup(e.target.files[0]);e.target.value=''}if(e.target.id==='focus-task'){ui.focusTask=e.target.value;persistFocus()}});
$('#mobile-menu').onclick=()=>{$('#sidebar').classList.add('open');$('#side-backdrop').classList.add('visible')};$('#side-backdrop').onclick=()=>{$('#sidebar').classList.remove('open');$('#side-backdrop').classList.remove('visible')};$('#profile-button').onclick=()=>goto('settings');document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
if('serviceWorker'in navigator&&['https:','http:'].includes(location.protocol)&&!location.hostname.includes('localhost')&&!window.Capacitor){navigator.serviceWorker.register('./sw.js').catch(()=>{})}
render();
})();
